    "descKr": "Room 313은 트라우마로 엉망이 된 마음의 방을 다시 정돈해 나가는 과정을 담은 일기 형식의 일러스트 북입니다. 평온하던 방에 어느 날 폭풍이 찾아오고, 주인공은 엉망이 된 방을 떠나 오래 방황합니다. 그러던 어느 날 낡은 일기장에서 과거의 자신이 남긴 글을 발견하고, 다시 방으로 돌아갈 용기를 얻습니다. 방치되어 있던 방은 소소한 행위로 하나씩 가꾸어지고, 주인공은 타인과의 만남을 통해 더 이상 방에 기대지 않고 바깥으로 나아갑니다.\n누구에게나 마음이 머무는 방이 하나쯤 있습니다. 이 작품 속 방은 곧 자기 자신이며, 사람을 일으키는 것은 거창한 계기가 아니라 작은 행위와 관계라고 말합니다. 지금 당신의 방은 어떤 모습이고, 무엇을 들여놓고 싶으신가요. 이 질문이 힘든 마음을 지나 다시 일어서 나아가는 작은 계기가 되기를 바랍니다.",
    "descEn": "『Room 313』is an illustrated book in diary form about tidying a room of the heart left in ruins by trauma. One day a storm reaches the once-peaceful room, and the main character leaves it behind and wanders for a long time. Then, in an old diary, she finds words written by her past self and gathers the courage to go back. The neglected room is tended again through small acts, and through meeting others she no longer leans on it but steps out into the world.\nEveryone has a room where the heart stays. The room in this work is the self, and it says that what lifts a person is not some grand turning point but small acts and small relationships. What does your room look like now, and what would you like to bring into it? I hope this question becomes a small beginning for standing up and moving forward again.",
