    "descKr": "오랫동안 사회는 임산부를 아름답게 표현하고 수동적인 약자로 여겨왔습니다. 그러나 임신은 단순히 아름답지만은 않으며 그 과정을 견디는 임산부는 오히려 강인하다 할 수 있습니다. ORIGO는 임산부를 수동적 존재가 아니라 하나의 세계를 창조하는 능동적 주체로 신격화를 통해 재정의하는 인식 변화 캠페인 브랜드입니다. 신격화는 지금까지 모성으로 전개된 미화의 방식과 다르게 창조의 흔적과 긴장감을 그대로 담아 이상화된 모습을 탈피합니다. 오브제는 검은 알을 사용해 그 위에 새겨지는 균열(crack)과 빛은 창조의 과정을 나타냅니다. 균열은 결함이 아니라 창조의 흔적으로 재해석되어 변화의 흔적을 숨겨야 한다는 사회적 시선에 저항합니다. 임산부는 태아의 세상을 창조한다는 점에서 천지창조의 7일 개념을 임신 40주에 대입해 7단계 서사로 신화를 전개합니다.",
    "descEn": "For a long time, society has portrayed pregnant women as beautiful but passive. Yet pregnancy is not simply beautiful, and women who endure it are, in fact, strong. ORIGO is a campaign that redefines pregnant women not as passive vessels but as active creators of a world, through deification. Unlike the beautifying language of motherhood, this deification keeps the raw traces and tension of creation, rejecting an idealized image. Its core object is a black egg, on which cracks and light represent the process of creation, reinterpreted not as flaws but as marks of creation, resisting the gaze that demands change be hidden. As a pregnant woman creates the world of her unborn child, ORIGO maps Genesis's seven days onto the 40 weeks of pregnancy, unfolding it as a myth in seven stages.",
