    "title": "",
    "titleEn": "Bon Confett!",
    "track": "경험디자인",
    "cat": "BX(브랜드)",
    "descKr": "스트리밍 시대가 되며 음악은 언제 어디서나 쉽게 듣고 공유할 수 있는 콘텐츠가 되었습니다. 그 과정에서 음악을 손에 쥐고 건네던 물질적인 경험은 점차 희미해졌지만, 사람들은 여전히 굿즈와 피지컬 음반 등 만질 수 있는 음악을 원하고, SNS를 통해 한 곡의 음악으로 말보다 깊은 마음을 전하곤 하죠. 음악은 이제 감정을 담아 전하는 하나의 언어가 되었고, 그 언어는 누군가에게 건네질 때 더욱 특별한 의미를 갖습니다.\nBon Confett!는 음악과 선물을 하나의 경험으로 연결합니다. 단순히 플레이리스트나 음반을 전달하는 것이 아니라, 한 곡에 담긴 감정과 메시지를 편지와 오브제, 그리고 음악이 차례로 펼쳐지는 경험으로 재구성하여 음악을 오래 기억될 선물로 완성합니다. Bon Confett!와 함께, 말 대신 음악으로 마음을 선물해 보세요.",
    "descEn": "When was the last time you gave someone a piece of music? We listen to and share music every day. In the age of streaming, music has become something we can access anytime, anywhere. While the experience of physically giving music has faded, people still use songs to express feelings that words cannot. Music has become a language of emotion, and it becomes even more meaningful when shared with someone else.\nBon Confett! reimagines music as a gift. Rather than simply sharing a playlist or an album, it transforms the emotions and messages within a song into letters, objects, and a carefully designed experience—creating a gift that lasts far beyond the moment it is given. Give your heart through music with Bon Confett!.",
    "video": "",
    "tags": [
     "#브랜딩",
     "#그래픽"
    ],
