    "title": "",
    "titleEn": "Note Grammar",
    "track": "콘텐츠디자인",
    "cat": "편집",
    "descKr": "악보는 음악을 표현하는 하나의 언어이다. 언어에 문자, 문장, 문단, 문장부호 등이 존재하는 것처럼, 악보 역시 음표, 마디, 악장, 보표 등으로 이루어져 있다. 뿐만 아니라 세상에 여러 언어가 존재하는 것처럼 악보 역시 다양한 형태를 띄고 있다. 그러나 오늘날 음악은 스트리밍과 알고리즘을 통해 소비되며 악보를 직접 읽고 경험하는 일은 점차 줄어들었다. 그저 연주를 위한 도구로 인식될 뿐, 악보가 지닌 시각적 언어와 구조는 충분히 조명받지 못하고 있다.\nNote Grammar는 음악의 언어로써 작용하는 악보의 역사와 서로 다른 기보법의 구조를 그래픽적으로 분석한다. 이를 통해 기보법이 공유하는 시각적 원리를 도출하고, 새로운 그래픽 언어로 재구성하여 음악을 ‘듣는 것’에서 ʻ‘보는 것’으로 확장하는 시각적 경험을 제안한다.",
    "descEn": "Musical notation is a language that expresses music. Like written language, it has its own grammar of notes, measures, and staves, and has evolved into many different forms. Yet today, as music is consumed through streaming and algorithms, the experience of reading notation is gradually disappearing. More than a tool for performance, notation is a visual language with its own structure and logic.\nNote Grammar explores the history and structures of different notation systems, uncovering their shared visual principles and translating them into a new graphic language. Through this process, the project expands music from something we hear into something we see.",
    "video": "",
    "tags": [
     "#편집디자인",
     "#타이포그래피",
     "#음악"
    ],
    "booth": "3F C12",
    "thumb": "images/works/Thumbnail/23100983_Note Grammar_Thumbnail.webp",
