    "titleEn": "TOFFICE.9to6",
    "track": "콘텐츠디자인",
    "cat": "일러스트",
    "descKr": "《TOFFICE.9to6》는 신입사원 마토의 첫 출근과 오피스 라이프를 담은 일러스트 스토리북입니다.\n오전 9시부터 오후 6시까지, 반복되는 업무와 관계 속에서 각자의 속도로 익어가는 토마토들.\n숙성, 압착, 훈연, 균열. 저마다 다른 흔적을 지닌 동료들 사이에서 마토는 낯선 오피스 생활을 배워갑니다.\n오후 6시가 되면, 마토는 얼마나 익어 있을까요?",
    "descEn": "«TOFFICE.9to6» is an illustrated storybook about\nMato's first day at the office.\nFrom 9 a.m. to 6 p.m., each tomato ripens at its own pace amid daily tasks and workplace relationships.\nRipened, pressed, smoked, cracked. Every coworker bears a different mark of office life, and Mato learns the ropes among them.\nHow ripe will Mato be by 6 p.m.?",
