    "no": "1",
    "title": "파이버",
    "titleEn": "Fiber",
    "track": "경험디자인",
    "cat": "UX/UI",
    "descKr": "여러 금융 앱의 등장으로 소비 관리가 한결 편리해졌지만, 사용자는 여전히 파편화된 결제 내역과 수동적인 분석 기능 때문에 어려움을 겪고 있습니다. 특히 자동 기록과 분석에 머무르는 기존 금융 AI는 사용자가 스스로 소비를 판단하고 행동을 설계하도록 돕는 데 한계가 있습니다.\n\n피버는 이 문제를 해결하기 위해 '맥락을 이해하는 AI'로 한 걸음 더 나아간 금융 비서를 제안합니다. AI는 소비 시간, 장소, 동반자 등의 정보를 바탕으로 지출 맥락을 자동으로 정리하고, 사용자는 이를 직접 연결·수정·재구성하며 자신의 소비 흐름을 이해합니다.\n\n또한 마셜 제도의 스틱 차트에서 영감을 얻어 흩어진 소비 데이터를 하나의 흐름으로 연결함으로써, 개인의 소비 습관에 대한 인식을 높이고 주도적인 소비 관리를 지원합니다",
    "descEn": "As financial apps become more diverse, managing personal spending remains challenging due to fragmented payment records and passive analytical features. Existing financial AI primarily focuses on automation and efficiency, offering limited opportunities for users to actively interpret their spending and shape their financial behaviors. This project proposes a proactive personalized finance UX powered by context-aware AI. By analyzing contextual information such as time, location, and companions, AI automatically organizes spending records, while users can connect, edit, and reorganize them to understand their spending patterns. Inspired by the Marshall Islands stick charts, the design connects fragmented financial data into meaningful spending flows, supporting greater spending awareness and user agency.",
    "video": "",
    "tags": [
     "#핀테크",
     "#AI",
     "#UXUI"
    ],
    "booth": "2F E60",
    "thumb": "images/works/Thumbnail/21100878_Fiber_Thumbnail.webp",
