    "titleEn": "bello",
    "track": "경험디자인",
    "cat": "BX(브랜드)",
    "descKr": "bello는 염증성 장질환 환자들을 위한 체험형 브랜드 캠페인입니다. 질환 데이터를 바탕으로 만든 퍼스널 ID를 매개로 환자 간의 자연스러운 교류와 연결을 유도하고, 서로의 경험과 정보를 교류할 수 있는 오프라인 커뮤니티를 제공합니다. 질환과 증상을 고유한 시각 언어로 번역해 만든 자신만의 페르소나를 교류의 도구로 활용할 수 있고, 나아가 염증성 장질환에 대한 관심과 이해를 확장하는 사회적 매개체로 기능합니다.",
    "descEn": "bello is an experiential brand campaign for people living with inflammatory bowel disease (IBD). Using a personal ID created from individual disease data, bello encourages natural interaction and connection among patients while providing an offline community where they can exchange experiences and information. Patients can use their own personas, created by translating their conditions and symptoms into a unique visual language, as a tool for interaction and connection. Furthermore, bello serves as a social medium that expands awareness and understanding of inflammatory bowel disease.",
