    "no": "1",
    "title": "불새",
    "titleEn": "FIREBIRD",
    "track": "콘텐츠디자인",
    "cat": "일러스트",
    "descKr": "불새의 뜨거운 열기가 행성 위의 모든 것을 불태워 버리는 재앙의 주간. 부족민들은 즐겁게 축제를 벌이며 지하 깊숙한 곳에 있는 방공호로 향합니다. 척후병으로 선발된 당신은 부족민들을 위하여 하늘에서 내리쬐는 빛을 피해 고대 장치를 작동시켜 가며 방공호로 향하는 길을 열어야 합니다. 그러나, 정말 그것이 전부일까요? 척후병의 진짜 역할은 무엇일까요? 불새는 정말 실존할까요? 촌장은 무엇을 숨기고 있는 거죠? 「불새」는 2D 수직 스크롤 플랫포머 퍼즐 스토리 게임입니다. 불새의 뜨거운 빛에 노출되지 않고, 발판을 만들고 길을 움직여가며 아래로 안전하게 내려가는 것이 목표입니다. 플레이어는 낮 동안 퍼즐을 풀어 길을 만들고, 밤이 되면 NPC와의 상호작용을 나누며 스토리를 진행하게 됩니다. 부디 빛에 타 죽지 않게 조심하세요.",
    "descEn": "The Week of Disaster, when the Firebird’s scorching heat burns everything on the planet to ashes. The villagers joyfully hold a festival as they head to the deep underground shelter. Chosen as a scout, you must avoid the light beaming from the sky and activate ancient devices to clear the path to the shelter for your people. But is that truly all? What is the scout's real role? Does the Firebird actually exist? What is the village chief hiding? 「Firebird」 is a 2D vertical-scrolling platformer puzzle story game. Your goal is to descend safely by creating platforms and moving paths while avoiding exposure to the Firebird's burning light. Solve puzzles during the day to clear the path, and interact with NPCs at night to progress the story. Be careful not to burn to death in the light.",
    "video": "",
    "tags": [
     "#일러스트레이션",
     "#아트북",
     "#게임"
    ],
    "booth": "1F C41",
    "thumb": "images/works/Thumbnail/22101020_FIREBIRD_Thumbnail.webp",
