    "no": "2",
    "title": "",
    "titleEn": "RESONA",
    "track": "콘텐츠디자인",
    "cat": "영상",
    "descKr": "RESONA는 Resonance와 Persona를 결합한 단어로, '자아의 공명'을 의미합니다. 우리는 어린 시절 저마다의 꿈을 품지만, 성인이 되며 현실의 압박과 두려움 속에서 그 꿈과 자신이 현재를 살아가는 이유를 잊은 채 살아가기도 합니다.\n본 작품은 당신은 지금 어떤 생각으로 현재를 살아가고 있는가?,어른이 되었다는 이유로 어린 시절의 꿈을 포기하고 있는가?라는 질문에서 출발합니다. 이를 SF 장르로 풀어내어, 미지의 존재에게 침략당한 지구를 지키기 위해 홀로 출격하는 조종사의 이야기를 담았습니다. 주인공은 공포와 주변의 압박 속에서 위협에 맞서며, 잊고 있던 어린 시절의 꿈과 다시 마주하고 자신의 내면에 귀 기울이며 앞으로 나아갑니다.",
    "descEn": "RESONA is a combination of Resonance and Persona, representing the resonance of the self. As children, we each carry dreams, yet as we grow into adulthood, we often forget those dreams―and even the reasons why we continue to live the way we do―under the pressures and fears of reality. This work begins with the questions: What thoughts guide the way you live today? and Have you given up on your childhood dreams simply because you became an adult? Through the science-fiction story of a pilot who sets out alone to defend Earth from an unknown extraterrestrial threat, RESONA portrays a journey of confronting fear, rediscovering a forgotten childhood dream, and finding the strength to move forward by reconnecting with one's inner self.",
