  "works": [
   {
    "no": "1",
    "title": "",
    "titleEn": "Me On A Plate",
    "track": "콘텐츠디자인",
    "cat": "일러스트",
    "descKr": "머릿속의 아이디어는 완벽해 보이는데, 왜 손을 거치면 초라해 보일까?\n\n이 프로젝트는 디자이너로서의 솔직한 열등감과 고민에서 출발하여, 창작 과정에서 디자이너로써 느꼈던 스스로의 고충과 성장을 요리에 비유하여, 자신만의 색깔이 담긴 한 그릇을  만들어내는 과정을 담아낸 이야기입니다.\n\n디자인은 요리와 비슷하다고 생각합니다. 훌륭한 요리가 신선한 재료, 정교한 레시피, 그리고 멋진 플레이팅이 어우러져 완성되듯, 좋은 디자인 역시 좋은 아이디어, 명확한 기획과 의도, 그리고 직관적인 시각화가 조화를 이룰 때 탄생하기 때문입니다. 이 책을 읽게 될 창작자들이 자신이 가진 재료를 맛있는 요리로 탄생시키는 것을 포기하지 않았으면 하는 마음에서 제작하게 되었습니다.",
    "descEn": "“Why do ideas look so perfect in my head, but somehow fall short once I try to bring them to life?”\nThis project began with my own insecurities and struggles as a designer. By comparing the creative process to cooking, it tells a story about the challenges and growth I experienced while learning how to turn my ideas into something that truly reflects my own style.\nI believe design is a lot like cooking. A great dish comes together through fresh ingredients, a well-planned recipe, and thoughtful plating. In the same way, good design is created when a strong idea, a clear concept and intention, and intuitive visual expression work together in harmony.\nI created this book with the hope that other creators will not give up on turning their ideas into a dish of their own—something meaningful and uniquely theirs.",
    "video": "",
    "tags": [],
    "booth": "1F C59",
    "thumb": "images/works/Thumbnail/24110075_Me On A plate_Thumbnail.webp",
    "imgs": [
     "images/works/webportfolio/24110075_Me On A Plate_work1.webp",
     "images/works/webportfolio/24110075_Me On A Plate_work2.webp",
     "images/works/webportfolio/24110075_Me On A Plate_work3.webp"
    ]
   },
   {
    "no": "2",
    "title": "오비스",
    "titleEn": "Ovice",
    "track": "경험디자인",
    "cat": "CX(서비스디자인)",
    "descKr": "AI와 함께하는 일은 꼭 딱딱해야 할까요?\nOvice 는 보이지 않는 AI 에이전트의 작업 과정을 하나의 가상 오피스로 시각화합니다. 사용자는 오피스를 바라보는 것만으로도 에이전트가 어떤 일을 하고 있는지, 작업은 어디까지 진행되었는지, 어떤 태스크가 완료되었는지 직관적으로 확인할 수 있습니다. 화면 속 에이전트들은 명령을 수행하는 도구를 넘어, 나와 같은 공간에서 함께 일하는 친구이자 동료가 됩니다. 일을 시작하고, 자리를 옮기고, 회의에 참석하고, 서로 협력하며 태스크를 완성하는 모습을 지켜보는 과정은 마치 작은 게임을 플레이하는 것처럼 느껴집니다.\n일을 관리하는 대신, 나만의 팀을 플레이하세요.\n지루했던 업무가 하나의 퀘스트가 되고, AI와의 협업이 하나의 놀이가 됩니다.",
    "descEn": "Does working with AI always have to feel like work?\nOvice transforms the invisible work of AI agents as a playful,  living virtual office. At a glance, you can see who is working on what, how far each task has progressed, and what has already been completed. When needed, you can step in, adjust their roles, and orchestrate how your agents work together. Your agents are more than tools waiting for commands. They become friends and teammates sharing the same workspace with you. Watching them work, move around the office, gather for meetings, collaborate, and complete tasks turns everyday workflows into something closer to playing a game.\nDon’t just manage your work. Play your team.\nHere, tedious tasks become quests, and collaborating with AI becomes part of the fun.\nWelcome to Ovice.",
    "video": "",
    "tags": [],
    "booth": "3F E46",
    "thumb": "images/works/Thumbnail/24110075_Ovice_Thumbnail.webp",
    "imgs": [
     "images/works/webportfolio/24110075_Ovice_work1.webp",
     "images/works/webportfolio/24110075_Ovice_work2.png",
     "images/works/webportfolio/24110075_Ovice_work3.webp"
    ]
   }
  ]
