    "titleEn": "dubi",
    "track": "경험디자인",
    "cat": "CX(서비스디자인)",
    "descKr": "두비는 정답과 기술 습득에 치우친 입시 중심의 \n미술교육에서 벗어나, 학생들이 스스로 보고 생각하며 \n미적 감수성과 창의력을 키울 수 있도록 돕는 \nAI 기반 미술교육 플랫폼입니다. 거장 아티스트의 \n작품과 생애, 표현 방식 등의 데이터를 학습한 AI와 \n대화하며 작품에 담긴 의미와 예술가의 관점을 \n자연스럽게 이해할 수 있습니다. \n또한 학생의 관심 분야와 학습 수준에 맞춘 개인화된 \n콘텐츠와 대화형 레슨, 창작 활동 및 피드백을 제공해 \n단순한 미술 지식 습득을 넘어 자신의 생각을 \n시각적으로 표현하는 능력을 기를 수 있도록 돕습니다.",
    "descEn": "dubi is an AI-powered art education platform \ndesigned to move beyond answer-driven, \nexam-focused learning and foster independent \nthinking, creativity, and artistic sensitivity. \nThrough interactive conversations with AI informed \nby the works, lives, and artistic approaches \nof renowned artists, students can naturally explore \nartistic perspectives and discover deeper \nmeanings behind artworks.\nWith personalized lessons, creative activities, \nand feedback tailored to each learner’s interests \nand level, dubi encourages students to go beyond \nsimply acquiring knowledge and develop the ability \nto express their own ideas visually. Ultimately, \ndubi aims to make high-quality art education \nmore accessible, creating a flexible learning \nenvironment where anyone can freely explore, \nunderstand, and enjoy art.",
