    "title": "",
    "titleEn": "Sparkzz",
    "track": "콘텐츠디자인",
    "cat": "일러스트",
    "descKr": "Sparkzz는 한 사람이 자신이 좋아하는 것을 발견하고 \n점차 몰입해가는 과정을 따라가며, \n그 여정 속에서 재즈라는 장르의 다양한 감각과 \n매력을 함께 소개하는 그래픽 노블 프로젝트입니다. \n피아노 연주, 레코드바, 라이브 공연, 재즈 페스티벌 등 \n실제 경험을 바탕으로 서사를 구성하였으며, \n재즈를 접하는 순간의 감정과 분위기를 \n시각적으로 풀어냈습니다.\n특히 눈에 보이지 않는 소리와 음악적 감각을 색채, \n형태, 질감, 화면의 흐름과 같은 그래픽 요소로 변환하며, \n추상적인 음을 시각 언어로 옮기는 다양한 \n표현 방식을 실험하였습니다. \n이를 통해 재즈라는 장르를 설명하는 데 그치지 않고, \n좋아하는 것을 발견한 사람이 자신만의 \n취향과 감각을 형성해가는 과정까지 함께 \n전달하고자 하였습니다.",
    "descEn": "Sparkzz is a graphic novel project that follows an individual’s journey of discovering a passion and becoming deeply immersed in it, while exploring the diverse sensations and appeal of jazz. Drawing on personal experiences—such as playing the piano, visiting vinyl listening bars, attending live performances, and going to jazz festivals—the project visually captures the emotions and atmosphere of encountering jazz. It also experiments with translating abstract sounds into a visual language through color, form, texture, and visual flow. Rather than simply explaining jazz as a genre, Sparkzz portrays how discovering something to love can shape one’s individual taste and sensibility.",
