    "no": "1",
    "title": "분식 한 판: 외국인 위한 보드게임",
    "titleEn": "Bunsik Showdown Board Game",
    "track": "경험디자인",
    "cat": "CX(서비스디자인)",
    "descKr": "분식 한 판은 한국 분식과 음식 문화에 관심 있는 외국인을 위한 에듀테인먼트 보드게임이다. 플레이어는 주문 카드를 받고 필요한 재료를 모아 5턴 안에 요리를 완성해야 한다. 게임 중에는 다른 플레이어와 재료를 자유롭게 교환하거나 상대의 재료를 가져올 수 있으며, 다양한 특수 카드의 효과로 예상하지 못한 상황이 발생하기도 한다. 이러한 요소는 단순한 재료 수집을 넘어 경쟁과 협력, 전략적인 선택을 유도한다. 플레이어는 게임을 진행하며 떡볶이, 라면, 김밥 등 대표적인 분식 메뉴의 이름과 주요 재료를 자연스럽게 익히고, 한국의 길거리 음식 문화를 쉽고 재미있게 경험할 수 있다.",
    "descEn": "“Bunsik Showdown” is an edutainment board game for international players interested in Korean street food and culture. Each player receives an order card, collects the required ingredients, and must complete the dish within five turns. During the game, players can trade ingredients, take cards from opponents, and face unexpected situations triggered by special cards. Through competition, cooperation, and strategic choices, players naturally learn the names and key ingredients of popular dishes such as tteokbokki, ramyeon, and gimbap while enjoying Korean street food culture in an interactive and playful way.",
