    "cat": "일러스트",
    "descKr": "WARIS는 말레이어로 \"계승자\"를 뜻하며, 브루나이 출신인 작가의 시선으로 브루나이 7개 원주민 집단의 문화적 정체성을 재해석한 일러스트레이션 기반 패턴 디자인 프로젝트이다. 리서치와 인터뷰를 통해 각 집단의 생활 방식, 신념, 전통 요소에서 키워드와 모티프를 추출하고, 이를 스티플과 그레인 질감의 통일된 시각 언어로 발전시켰다. 최종 결과물은 믹스드 미디어 아티스트 북을 중심으로, 헤드스카프 디자인 시리즈와 스티커팩으로 확장된다.",
    "descEn": "WARIS, meaning \"heir\" in Malay, is an illustration-based pattern design project that reinterprets the cultural identities of Brunei's seven indigenous groups from the perspective of a Bruneian designer. Through research and interviews, the project extracts keywords and motifs from each group's lifestyle, beliefs, and traditional elements, then translates them into a unified visual language using stipple and grain textures. Centered on a mixed-media artist book, the final work expands into a headscarf design series and motif sticker pack.",
