    "cat": "UX/UI",
    "descKr": "KEPADAKU는 생각과 감정을 표현하고 정리하는 데 어려움을 느끼는 사용자를 위한 정서적 웰빙 기반의 성찰 서비스이다. 감정 체크인과 AI 기반 성찰 프롬프트를 통해 기록의 시작을 돕고, 글·음성·영상 중 자신에게 편한 방식으로 감정을 남길 수 있도록 설계했다. 기록 아카이브와 월별 성찰 리캡을 통해 사용자는 지난 기록을 다시 돌아보며 자신의 생각과 감정을 시간의 흐름 속에서 이해할 수 있다. 최종적으로 모바일 UX/UI 프로토타입과 전시 경험을 위한 시각적·오프라인 요소로 확장했다.",
    "descEn": "KEPADAKU is a reflection service for emotional well-being designed for people who find it diﬃcult to express and organize their thoughts and feelings. A simple mood check-in and AI-guided reflection prompts help users begin without pressure, while writing, voice, and video oﬀer flexible ways to reflect. A personal archive and monthly reflection recap encourage users to revisit past entries and understand their thoughts and emotions over time. The final outcome includes a mobile UX/UI prototype together with visual and oﬄine elements developed for the exhibition experience.",
