    "cat": "BX(브랜드)",
    "descKr": "이제는 우리가 깨물 차례! Bugbite는 할로윈이라는 특별한 날을 통해 곤충식이 주는 혐오감을 즐길 수 있는 컨텐츠로 바꿔버리는 파티 테마 곤충식 브랜드입니다.\n곤충식의 장점에도 불구하고 아직은 거부감이 든다는 여론이 많다는 점, 그런데도 곤충식 먹방 등이 컨텐츠로서의 인기와 주목도가 높다는 점에 주목하여 곤충식에 대해 고착화된 편견을 깨는 것을 브랜드 목표로 삼습니다.",
    "descEn": "Now it’s our time to bite! Bugbite is a party-themed edible insect dessert brand that turns the aversion to eating insects into a form of entertainment through the special occasion of Halloween.\nDespite the advantages of insect-based meals, public opinion still shows a lot of resistance; however, recognizing the high popularity and attention they receive as media content, the brand aims to break the entrenched prejudices surrounding them.",
