    "title": "살, 뼈, 힘",
    "titleEn": "Flesh, Bones, and Strength",
    "track": "콘텐츠디자인",
    "cat": "일러스트",
    "descKr": "모든 생물은 다들 나름의 힘과 살과 뼈를 가지고 살아간다. 거기에는 당연히 통상적으로 징그럽다고 여겨지는 생물들도 포함된다. \n<살, 뼈, 힘>에서는 불쾌하고 징그러운 생물의 시각적 이미지를 아름답고 재미있게 추상화한다. ‘징그럽다’는 인식을 가진 요소들을 활용하여 관객에게 새로운 아름다움을 찾는 재미를 선사하는 것을 최종 목표로 가진다.\n관객으로 하여금 징그럽다고 여겨지는 것들이 얼마나 아름다울 수 있는지, 그들 나름의 아름다움이 얼마나 예술적인 소재로 충분한 자질을 가지고 있는지 생각해 보는 계기를 갖도록 한다.",
    "descEn": "All living beings live with their own flesh, bones and strength. Of course, including creatures that are generally considered disgusting. \nIn <Flesh, Bones, and Strength>, the visual images of unpleasant and grotesque creatures are abstracted in a beautiful and engaging way. The ultimate goal is to offer the audience the pleasure of discovering new beauty by utilizing elements that evoke a sense of disgust.\nIt invites the audience to reflect on how things considered disgusting can be beautiful and how their own forms of beauty possess enough qualities to serve as artistic material.",
