    "cat": "BX(브랜드)",
    "descKr": "도시는 하루 종일 소리와 빛, 사람과 냄새로 가득하다. \n우리는 매일 감당하기 어려운 자극 속에 놓이지만, 감각의 피로는 눈에 보이지 않아 쉽게 지나쳐진다. 잠시 멈춰 감각을 추스를 곳이 필요해도 도시 안에 혼자 머물 수 있는 공간은 거의 없다. HOUSH는 도시 한가운데에 '감각의 온실'을 심는다. 지하철역, 사무실 로비, 도서관 같은 기존 건물 안에 1인 감각 회복 유닛을 두어 외부 자극을 걸러내고, 사용자가 청각·시각·촉각·후각·전정의 감각 환경을 자신의 상태에 맞게 직접 조절하도록 한다. 자극을 없애는 대신 각자에게 맞게 누그러뜨려, 도시를 떠나지 않고도 감각의 평온을 되찾게 하는 것이다. HOUSH는 도시 속에서 각자의 고요를 가꾸는 새로운 방식을 제안한다.",
    "descEn": "The city is filled with sound, light, people, and scent all day. We live amid more stimuli than we can easily bear, yet sensory fatigue goes unnoticed because it cannot be seen. Even when we need a moment to recover our senses, the city offers almost no space to be alone.\nHOUSH plants a \"sensory greenhouse\" in the middle of the city. It places single-person sensory recovery units inside existing buildings such as subway stations, office lobbies, and libraries, filtering out external stimuli and letting each user adjust the auditory, visual, tactile, olfactory, and vestibular environment to their own state. Rather than removing stimuli, HOUSH softens them to suit each person, helping users regain sensory calm without leaving the city. HOUSH proposes a new way to cultivate one's own quiet within the city.",
